/**
 * Provider-independent object storage interface. Application code depends on
 * this, never on a specific SDK, so the provider (Backblaze B2, Cloudflare R2,
 * AWS S3, Supabase S3, MinIO, ...) can change without touching callers.
 *
 * Keys are always generated by the server — never accepted from clients.
 */
export interface StorageProvider {
  /** Stored in files.storage_provider so data stays traceable across providers. */
  readonly name: string;

  /** Origin browsers upload to directly (needed for the CSP connect-src). */
  readonly uploadOrigin: string;

  /**
   * Short-lived URL the browser PUTs the file body to. The exact byte size is
   * part of the signature, so a larger/smaller body is rejected by storage.
   */
  createUploadUrl(
    key: string,
    options: { contentLength: number; expiresInSeconds: number }
  ): Promise<{ url: string; method: "PUT"; headers: Record<string, string> }>;

  /**
   * Short-lived URL for reading the object. "attachment" downloads it;
   * "inline" lets the browser display it (only used for safe preview types).
   * A fixed signingDate yields the same URL within a time window, so the
   * browser can cache previews.
   */
  createDownloadUrl(
    key: string,
    options: {
      fileName: string;
      contentType: string;
      expiresInSeconds: number;
      disposition?: "attachment" | "inline";
      cacheControl?: string;
      signingDate?: Date;
    }
  ): Promise<string>;

  /** Object size in bytes, or null when the object does not exist. */
  getObjectSize(key: string): Promise<number | null>;

  /** First `length` bytes of the object (for file signature checks). */
  readObjectStart(key: string, length: number): Promise<Uint8Array>;

  /** Deletes the object. Succeeds when the object is already gone. */
  deleteObject(key: string): Promise<void>;
}
